async function uploadFileToS3(file: File) {
  const signRes = await fetch('{{api_signing_endpoint}}', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ filename: file.name, contentType: file.type }),
  });
  const { url, key, headers } = await signRes.json();

  await new Promise<void>((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open('PUT', url);
    Object.entries(headers || {}).forEach(([k, v]) => xhr.setRequestHeader(k, v as string));
    xhr.upload.onprogress = (e) => {
      if (e.lengthComputable) console.log(`${Math.round((e.loaded / e.total) * 100)}%`);
    };
    xhr.onload = () => (xhr.status >= 200 && xhr.status < 300 ? resolve() : reject(new Error(`status ${xhr.status}`)));
    xhr.onerror = () => reject(new Error('network error'));
    xhr.send(file);
  });

  return { key };
}
